using System;
using System.Collections.Generic;
using FishNet;
using RyanAssets.GameFeel;
using RyanAssets.Retention.Client;
using TMPro;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UI;

namespace Universes.UniverseData.tycoon.Client {
    /// <summary>
    /// Brick Tycoon's HUD: wallet card (with a counting cash number and the rush-hour timer), collector
    /// gauge, the next goal, build list, hint bar, toasts, the "while you were away" card and the rebirth
    /// perk shop. Layout lives in the TycoonHUD prefab (generated by TY_HudAuthoring, which also nests the
    /// retention kit's level chip, challenges and summary card); this binds data. Sounds live in
    /// <see cref="TY_Feedback"/>.
    /// </summary>
    public sealed class TY_Hud : MonoBehaviour {
        [Header("Wallet")]
        public TMP_Text plotTitle;
        public TMP_Text cash, income, multiplier;
        public GameObject multiplierPill;
        public GameObject rebirthBadge;
        public TMP_Text rebirthText;
        [Tooltip("Seconds the cash number takes to count to a new total.")]
        [Min(0.01f)] public float cashCountSeconds = 0.6f;
        [Tooltip("Punch on the cash number when a collection or coin lands.")]
        [Range(0f, 1f)] public float cashPunch = 0.15f;

        [Header("Rush hour")]
        public GameObject rushPill;
        public TMP_Text rushText;

        [Header("Goal and welcome back")]
        public TY_GoalCard goalCard;
        public TY_OfflineCard offlineCard;
        [Tooltip("Seconds the wallet takes to count up when the welcome-back card's cash lands.")]
        [Min(0.05f)] public float offlineLandSeconds = 1.2f;

        [Header("Retention kit")]
        [Tooltip("The kit's rebirth summary card: the tycoon's toasts wait while it is open, so none sits on it.")]
        public RetentionSummaryCard summaryCard;
        [Tooltip("Most toasts held back while the summary card is open (the oldest are dropped).")]
        [Range(1, 8)] public int maxHeldToasts = 4;

        [Header("Collector")]
        public Image collectorFill;
        public TMP_Text collectorText, collectorState;
        public Color collectorNormal = new(0.3f, 0.75f, 1f), collectorFull = new(1f, 0.35f, 0.35f), collectorAuto = new(0.2f, 0.85f, 0.55f);

        [Header("Build list")]
        public GameObject buildPanel;
        [Tooltip("The lane list inside the build plan; the plan's header folds it away.")]
        public GameObject planBody;
        public Button planToggle;
        public Image planChevron;
        public Sprite planOpenIcon, planClosedIcon;
        public Key planKey = Key.B;
        public Image buildFill;
        public TMP_Text buildText;
        public TY_BuildCard[] laneCards;
        public GameObject rebirthCard;
        public TMP_Text rebirthCardPrice;
        [Tooltip("What the next rebirth brings (multiplier, tokens, the landmark it opens).")]
        public TMP_Text rebirthCardInfo;
        public Image rebirthCardFill;

        [Header("Hint")]
        public TMP_Text hint;
        public Image hintIcon;
        public Sprite hintClaim, hintBuild, hintCollect, hintWait;

        [Header("Toast")]
        public CanvasGroup toast;
        [Tooltip("Toast fade in/out speed, in alpha per second.")]
        [Min(0.1f)] public float toastFadeSpeed = 6f;
        [Tooltip("Seconds a toast stays up, per kind of event.")]
        [Min(0.5f)] public float toastBoughtSeconds = 2.5f, toastCollectedSeconds = 2f, toastDeniedSeconds = 2.5f, toastRebirthSeconds = 5f,
            toastGoldSeconds = 3f, toastPerkSeconds = 3f, toastFullSeconds = 3.5f, toastRushOverSeconds = 3f, toastDefaultSeconds = 3f;
        public Image toastAccent, toastIcon;
        public TMP_Text toastText;
        public Sprite iconBought, iconCash, iconDenied, iconRebirth, iconGolden, iconPerk, iconInfo, iconFull, iconRush, iconGoal, iconChest;
        public Color toastBought = new(0.2f, 0.78f, 0.48f), toastCash = new(0.24f, 0.55f, 1f), toastDenied = new(0.95f, 0.33f, 0.36f),
            toastRebirth = new(1f, 0.42f, 0.84f), toastGold = new(1f, 0.79f, 0.24f), toastFull = new(1f, 0.71f, 0.28f), toastRush = new(1f, 0.62f, 0.15f),
            toastGoal = new(0.36f, 0.85f, 1f);
        [Min(0.5f)] public float toastGoalSeconds = 3.5f, toastChestSeconds = 3.5f;

        [Header("Perk shop")]
        public Button perksButton;
        public TMP_Text perksButtonTokens;
        public GameObject perksPanel;
        public Button perksClose;
        public TMP_Text perksTokens;
        public TY_PerkRow[] perkRows;
        [Tooltip("Key that opens and closes the perk shop.")]
        public Key perksKey = Key.P;

        TY_WalletBroadcast wallet;
        bool hasWallet;
        float toastUntil;

        readonly struct HeldToast {
            public readonly Sprite icon;
            public readonly Color color;
            public readonly string text;
            public readonly float seconds;
            /// <summary>A reward worth reading (a goal, the chest, a rebirth, a perk): the next toast waits for it.</summary>
            public readonly bool keep;
            public HeldToast(Sprite icon, Color color, string text, float seconds, bool keep = false) {
                this.icon = icon; this.color = color; this.text = text; this.seconds = seconds; this.keep = keep;
            }
        }

        readonly Queue<HeldToast> heldToasts = new();
        HeldToast shownToast;
        bool SummaryOpen => summaryCard != null && summaryCard.Visible;
        double cashShown, cashFrom, cashTarget;
        long cashTextKey = long.MinValue;
#if UNITY_EDITOR
        // Editor-only diagnostics for test probes: how often the cash text was rewritten (stays put while the number does not change).
        int cashTextWrites;
#endif
        float cashCount = 1f;
        float rushEndsAt;
        int rushShownSeconds = -1;

        void Awake() {
            toast.alpha = 0f;
            perksPanel.SetActive(false);
            rebirthBadge.SetActive(false);
            rebirthCard.SetActive(false);
            buildPanel.SetActive(false);
            planToggle.onClick.AddListener(TogglePlan);
            SetPlanOpen(false);
            goalCard.gameObject.SetActive(false);
            perksButton.onClick.AddListener(TogglePerks);
            perksClose.onClick.AddListener(TogglePerks);
            foreach (var row in perkRows) row.Upgrade += RequestPerk;
            offlineCard.Closed += OfflineLanded;
            plotTitle.text = "BRICK TYCOON";
            ShowCash(0);
            income.text = "";
            multiplierPill.SetActive(false);
            rushPill.SetActive(false);
            SetHint("Connecting...", hintWait);
        }

        void OnDestroy() {
            perksButton.onClick.RemoveListener(TogglePerks);
            perksClose.onClick.RemoveListener(TogglePerks);
            planToggle.onClick.RemoveListener(TogglePlan);
            foreach (var row in perkRows) row.Upgrade -= RequestPerk;
            if (offlineCard != null) offlineCard.Closed -= OfflineLanded;
        }

        void Update() {
            HoldToastsForSummary();
            float target = Time.unscaledTime < toastUntil ? 1f : 0f;
            toast.alpha = Mathf.MoveTowards(toast.alpha, target, Time.unscaledDeltaTime * toastFadeSpeed);
            CountCash();
            TickRush();
            var keyboard = Keyboard.current;
            if (keyboard != null && keyboard[perksKey].wasPressedThisFrame && !TextFieldFocused()) TogglePerks();
            if (keyboard != null && keyboard[planKey].wasPressedThisFrame && !TextFieldFocused() && buildPanel.activeSelf) TogglePlan();
        }

        void TogglePlan() => SetPlanOpen(!planBody.activeSelf);

        void SetPlanOpen(bool open) {
            planBody.SetActive(open);
            planChevron.sprite = open ? planOpenIcon : planClosedIcon;
        }

        static bool TextFieldFocused() {
            var selected = UnityEngine.EventSystems.EventSystem.current != null ? UnityEngine.EventSystems.EventSystem.current.currentSelectedGameObject : null;
            return selected != null && selected.GetComponent<TMP_InputField>() != null;
        }

        // ---------------------------------------------------------------- cash counter and rush timer
        /// <summary>The wallet's cash as shown: what the open welcome-back card pays lands when it closes.</summary>
        long ShownCash(long walletCash) => Math.Max(0L, walletCash - offlineCard.Pending);

        /// <summary>The welcome-back card closed: its cash counts up into the wallet.</summary>
        void OfflineLanded(long amount) {
            if (!hasWallet || amount <= 0) return;
            SetCash(wallet.cash, offlineLandSeconds);
            PunchCash();
        }

        float countSeconds;

        void SetCash(long value, float seconds = -1f) {
            countSeconds = seconds > 0f ? seconds : cashCountSeconds;
            if (!hasWallet) { cashShown = cashTarget = value; cashCount = 1f; ShowCash(value); return; }
            if (value == cashTarget) return;
            cashFrom = cashShown;
            cashTarget = value;
            cashCount = 0f;
        }

        /// <summary>Counts the cash number towards its target (ease-out) instead of snapping.</summary>
        void CountCash() {
            if (cashCount >= 1f) return;
            cashCount = Mathf.Min(1f, cashCount + Time.unscaledDeltaTime / Mathf.Max(0.01f, countSeconds));
            float eased = 1f - (1f - cashCount) * (1f - cashCount) * (1f - cashCount);
            cashShown = cashCount >= 1f ? cashTarget : cashFrom + (cashTarget - cashFrom) * eased;
            ShowCash((long)System.Math.Floor(cashShown));
        }

        /// <summary>
        /// Rewrites the cash text only when what it shows changes: whole dollars below 10K (written
        /// without allocating), the shown digits of "12.5K" / "3.25M" above that.
        /// </summary>
        void ShowCash(long value) {
            long key = CashTextKey(value);
            if (key == cashTextKey) return;
            cashTextKey = key;
#if UNITY_EDITOR
            cashTextWrites++;
#endif
            if (value >= 0 && value < 10_000) cash.SetText("${0}", value);
            else cash.text = "$" + TY_Catalog.Money(value);
        }

        /// <summary>Changes exactly when <see cref="TY_Catalog.Money"/>'s text for <paramref name="value"/> can change.</summary>
        static long CashTextKey(long value) =>
            value < 10_000 ? value
            : value < 1_000_000 ? (1L << 40) + value / 50 // "0.#" K: steps of $100, rounded, so check every $50
            : value < 1_000_000_000 ? (2L << 40) + value / 5_000 // "0.##" M: steps of $10K
            : (3L << 40) + value / 5_000_000; // "0.##" B

        /// <summary>Bumps the cash number (a collection or a gold coin just paid out).</summary>
        public void PunchCash() => Punch.Scale(cash.transform, cashPunch);

        void TickRush() {
            int seconds = Mathf.CeilToInt(rushEndsAt - Time.unscaledTime);
            bool active = hasWallet && seconds > 0;
            if (rushPill.activeSelf != active) rushPill.SetActive(active);
            if (!active || seconds == rushShownSeconds) return;
            rushShownSeconds = seconds;
            rushText.text = $"RUSH x{wallet.rushMultiplier:0.#}  {seconds}s";
        }

        void TogglePerks() {
            perksPanel.SetActive(!perksPanel.activeSelf);
            RefreshPerks();
        }

        void RequestPerk(TY_PerkId perk) {
            if (InstanceFinder.ClientManager != null && InstanceFinder.ClientManager.Started)
                InstanceFinder.ClientManager.Broadcast(new TY_PerkRequest { perk = perk });
        }

        // ---------------------------------------------------------------- binding
        /// <summary>Redraws everything from the latest wallet and the player's plot (if any).</summary>
        public void Refresh(in TY_WalletBroadcast w, TY_PlotState? plot, TY_Map map) {
            SetCash(ShownCash(w.cash));
            wallet = w;
            hasWallet = true;
            rushEndsAt = Time.unscaledTime + w.rushSeconds;
            rebirthBadge.SetActive(w.rebirths > 0);
            rebirthText.text = $"x{TY_Catalog.RebirthMultiplier(w.rebirths):0.#}";
            perksButtonTokens.text = w.tokens.ToString();
            RefreshPerks();
            goalCard.gameObject.SetActive(true);
            goalCard.Show(w.goalIndex, w.goalProgress, w.goalReward);

            if (w.plot < 0 || plot == null) {
                plotTitle.text = "BRICK TYCOON";
                income.text = "Claim a plot to start earning";
                multiplierPill.SetActive(false);
                collectorFill.fillAmount = 0f;
                collectorText.text = "No plot yet";
                collectorState.text = "";
                buildPanel.SetActive(false);
                SetHint("Find a FREE PLOT and step on its glowing green pad to claim it.", hintClaim);
                return;
            }

            TY_PlotState p = plot.Value;
            plotTitle.text = $"TYCOON #{w.plot + 1}";
            income.text = $"+${TY_Catalog.Money(w.income)}/s";
            multiplierPill.SetActive(w.multiplier > 1.001f);
            multiplier.text = $"x{w.multiplier:0.##} boost";

            bool auto = TY_Catalog.AutoCollects(p.purchased);
            bool full = !auto && p.bank >= p.capacity;
            collectorFill.fillAmount = auto ? 1f : p.capacity > 0 ? Mathf.Clamp01((float)p.bank / p.capacity) : 0f;
            collectorFill.color = auto ? collectorAuto : full ? collectorFull : collectorNormal;
            collectorText.text = auto ? $"Banking ${TY_Catalog.Money(p.income)}/s straight to your wallet" : $"${TY_Catalog.Money(p.bank)} / ${TY_Catalog.Money(p.capacity)}";
            collectorState.text = auto ? "AUTO" : full ? "FULL" : "";
            collectorState.color = auto ? collectorAuto : collectorFull;

            RefreshBuildList(p, map);
            RefreshHint(p, auto, full);
        }

        void RefreshBuildList(in TY_PlotState p, TY_Map map) {
            buildPanel.SetActive(true);
            int owned = TY_Catalog.OwnedCount(p.purchased & TY_Catalog.BaseMask);
            buildFill.fillAmount = owned / (float)TY_Catalog.BaseCount;
            buildText.text = $"{owned}/{TY_Catalog.BaseCount} built";
            foreach (var card in laneCards) {
                int total = 0, built = 0;
                for (int i = 0; i < TY_Catalog.Count; i++)
                    if (TY_Catalog.Items[i].kind == card.lane) { total++; if (TY_Catalog.Owns(p.purchased, i)) built++; }
                int next = TY_Catalog.NextInLane(p.purchased, card.lane);
                if (next < 0) { card.ShowDone(total); continue; }
                bool locked = !TY_Catalog.Available(p.purchased, next, p.rebirths);
                card.Show(next, TY_Catalog.Price(next, p.rebirths), map.Picture(next), wallet.cash, locked, TY_Catalog.LockReason(p.purchased, next, p.rebirths), built, total);
            }
            bool canRebirth = TY_Catalog.Available(p.purchased, TY_Catalog.RebirthIndex, p.rebirths);
            rebirthCard.SetActive(canRebirth);
            if (canRebirth) {
                long price = TY_Catalog.RebirthPrice(p.rebirths);
                rebirthCardPrice.text = $"${TY_Catalog.Money(price)}";
                rebirthCardFill.fillAmount = Mathf.Clamp01((float)wallet.cash / price);
                rebirthCardInfo.text = RebirthPromise(p.rebirths);
            }
        }

        /// <summary>What the next rebirth brings, so the reset reads as a reward: "Income x2.5, +1 perk token, opens the Cargo Port".</summary>
        static string RebirthPromise(int rebirths) {
            int landmark = TY_Catalog.LandmarkOpenedBy(rebirths + 1);
            string opens = landmark >= 0 ? $", opens the {TY_Catalog.Items[landmark].name} landmark" : "";
            return $"Step on the pink pad: income x{TY_Catalog.RebirthMultiplier(rebirths + 1):0.#}, +perk token{opens}. Landmarks stay.";
        }

        void RefreshHint(in TY_PlotState p, bool auto, bool full) {
            int cheapest = -1;
            long cheapestPrice = 0;
            foreach (int i in TY_Catalog.AvailableItems(p.purchased, p.rebirths)) {
                long price = TY_Catalog.Price(i, p.rebirths);
                if (cheapest < 0 || price < cheapestPrice) { cheapest = i; cheapestPrice = price; }
            }
            if (p.golden) SetHint("A gold coin is on your plot! Run over it for a cash bonus.", iconGolden);
            else if (full) SetHint("Your collector is full. Step on the blue pad by the furnace!", iconFull);
            else if (wallet.chestReady) SetHint("Your daily chest is ready! It is next to where you spawn.", iconChest);
            else if (cheapest < 0) SetHint("Everything is built!", iconBought);
            else if (wallet.cash >= cheapestPrice)
                SetHint($"Step on the glowing {TY_Lanes.Title(TY_Catalog.Items[cheapest].kind).ToLowerInvariant()} pad to build {TY_Catalog.Items[cheapest].name}.", hintBuild);
            else if (!auto && p.bank > 0 && wallet.cash + p.bank >= cheapestPrice)
                SetHint("Collect at the blue pad by the furnace to afford your next build.", hintCollect);
            else SetHint($"Next: {TY_Catalog.Items[cheapest].name} for ${TY_Catalog.Money(cheapestPrice)}. Your droppers are earning.", hintWait);
        }

        void SetHint(string text, Sprite icon) {
            hint.text = text;
            if (icon != null) hintIcon.sprite = icon;
        }

        void RefreshPerks() {
            if (!perksPanel.activeSelf) return;
            int tokens = hasWallet ? wallet.tokens : 0;
            perksTokens.text = tokens == 1 ? "1 token" : $"{tokens} tokens";
            foreach (var row in perkRows) row.Show(hasWallet ? wallet.perks.Level(row.perk) : 0, tokens);
        }

        // ---------------------------------------------------------------- feedback
        public void ShowEvent(in TY_EventBroadcast e) {
            // A rush hour's start already has the chat line, the banner and the HUD pill: no toast as well.
            if (e.kind == TY_EventKind.RushHour) return;
            // Earnings while away get their own card instead of a toast.
            if (e.kind == TY_EventKind.OfflineEarnings) {
                offlineCard.Show(e.amount, e.extra, e.text);
                return;
            }
            if (e.kind == TY_EventKind.Goal) goalCard.Completed();
            (Sprite icon, Color color, float seconds) = e.kind switch {
                TY_EventKind.Bought or TY_EventKind.Claimed => (iconBought, toastBought, toastBoughtSeconds),
                TY_EventKind.Collected => (iconCash, toastCash, toastCollectedSeconds),
                TY_EventKind.TooPoor => (iconDenied, toastDenied, toastDeniedSeconds),
                TY_EventKind.Rebirth => (iconRebirth, toastRebirth, toastRebirthSeconds),
                TY_EventKind.GoldenBrick => (iconGolden, toastGold, toastGoldSeconds),
                TY_EventKind.Perk => (iconPerk, toastGold, toastPerkSeconds),
                TY_EventKind.CollectorFull => (iconFull, toastFull, toastFullSeconds),
                TY_EventKind.RushHourOver => (iconRush, toastRush, toastRushOverSeconds),
                TY_EventKind.Goal => (iconGoal, toastGoal, toastGoalSeconds),
                TY_EventKind.DailyChest => (iconChest, toastGold, toastChestSeconds),
                _ => (iconInfo, toastCash, toastDefaultSeconds),
            };
            bool keep = e.kind is TY_EventKind.Goal or TY_EventKind.DailyChest or TY_EventKind.Rebirth or TY_EventKind.Perk;
            var next = new HeldToast(icon != null ? icon : iconInfo, color, e.text, seconds, keep);
            // A reward toast on screen is not replaced at once: goals met together (or a goal and the chest)
            // come one after another; small news (a purchase) is dropped instead, the world shows it anyway.
            bool rewardUp = shownToast.keep && Time.unscaledTime < toastUntil;
            if (SummaryOpen || (rewardUp && keep)) Hold(next);
            else if (!rewardUp) ShowToast(next);
        }

        void ShowToast(in HeldToast t) {
            shownToast = t;
            toastText.text = t.text;
            toastIcon.sprite = t.icon;
            toastAccent.color = t.color;
            toastIcon.color = t.color;
            toastUntil = Time.unscaledTime + t.seconds;
        }

        void Hold(in HeldToast t) {
            while (heldToasts.Count >= maxHeldToasts) heldToasts.Dequeue();
            heldToasts.Enqueue(t);
        }

        /// <summary>
        /// While the kit's rebirth card is open, the tycoon's toasts wait (a toast already up is taken down
        /// and shown again after), so the card reads on its own; then they come back one after another.
        /// </summary>
        void HoldToastsForSummary() {
            float now = Time.unscaledTime;
            if (SummaryOpen) {
                if (now < toastUntil) {
                    // Show it again in full afterwards: it was up for a moment at most.
                    Hold(shownToast);
                    toastUntil = 0f;
                    toast.alpha = 0f;
                }
                return;
            }
            if (heldToasts.Count > 0 && now >= toastUntil && toast.alpha <= 0f) ShowToast(heldToasts.Dequeue());
        }
    }
}
